import AppKit

/// The Claude and OpenAI marks (as on awake.maben.gg), 64 px, for the Agents page.
enum BrandLogo {
    static let claude = image("")
    static let openAI = image("")

    private static func image(_ base64: String) -> NSImage {
        NSImage(data: Data(base64Encoded: base64) ?? Data()) ?? NSImage()
    }
}
